reference_pwsh:
Get-ChildItem site/img -Filter '*.jpeg' | Rename-Item -NewName { $_.BaseName + '.jpg' }
Get-ChildItem site -Filter '*.html' | ForEach-Object {
  $t = [IO.File]::ReadAllText($_.FullName)
  $n = $t -creplace '(src="img/[^"]+)\.jpeg"', '$1.jpg"'
  if ($n -cne $t) { [IO.File]::WriteAllText($_.FullName, $n) }
}
